<script setup lang="ts">
import {can} from './session'
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('ReplenishmentPanel')

import {ref,reactive,computed,onMounted,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api,session} from './session'
const props=defineProps<{initialStore:string}>(),emit=defineEmits(['navigate'])
const admin=computed(()=>can('replenishment','operate')),loading=ref(false),error=ref(''),data=ref<any>(null),page=ref(1),pageSize=ref(25),selected=ref<any[]>([])
const options=reactive({stores:[] as string[],warehouses:[] as any[]})
const filters=reactive({store:props.initialStore||'',region:'UK',q:'',only_need:false,only_linked:false,sort:'need'})
const format=(v:any)=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:2})
const stamp=(v:any)=>v?new Date(v).toLocaleString('zh-CN',{hour12:false}):'尚无记录'
const channelNames:Record<string,string>={air:'空派',truck:'卡航',sea:'海运'}
let sequence=0
async function load(){const seq=++sequence;loading.value=true;error.value='';selected.value=[];try{const p=new URLSearchParams({...Object.fromEntries(Object.entries(filters).map(([k,v])=>[k,String(v)])),page:String(page.value),page_size:String(pageSize.value)});const d=await api('/replenishment?'+p);if(seq===sequence)data.value=d}catch(e){if(seq===sequence){error.value=(e as Error).message;data.value=null}}finally{if(seq===sequence)loading.value=false}}
function search(){page.value=1;load()}
const detail=ref<any>(null)
const graph=computed(()=>{if(!detail.value)return '';const a=detail.value.projection,top=Math.max(1,...a.map((x:any)=>x.stock));return a.map((x:any,i:number)=>`${20+i/(a.length-1)*710},${160-x.stock/top*130}`).join(' ')})
const ruleDialog=ref(false),ruleBusy=ref(false),ruleError=ref(''),rule=reactive({safety_days:7,frequency_days:10,processing_days:7,revision:0})
function openRules(){Object.assign(rule,data.value.rule);ruleError.value='';ruleDialog.value=true}
async function saveRules(){ruleBusy.value=true;ruleError.value='';try{await api('/replenishment/rules',{store:filters.store,region:filters.region,...rule});ruleDialog.value=false;await load()}catch(e){ruleError.value=(e as Error).message}finally{ruleBusy.value=false}}
function uuid(){const b=new Uint8Array(16);crypto.getRandomValues(b);b[6]=(b[6]!&15)|64;b[8]=(b[8]!&63)|128;const s=Array.from(b,v=>v.toString(16).padStart(2,'0')).join('');return `${s.slice(0,8)}-${s.slice(8,12)}-${s.slice(12,16)}-${s.slice(16,20)}-${s.slice(20)}`}
const planDialog=ref(false),planBusy=ref(false),planError=ref(''),choices=ref<any[]>([]),warehouse=ref<number>(),ack=ref(false),requestId=ref('')
const uncertain=computed(()=>choices.value.some(x=>x.review_required))
const roundTen=(n:number)=>Math.floor((n+5)/10)*10
const planLimit=(x:any)=>Math.max(x.procurement_need||0,x.channels.reduce((n:number,c:any)=>n+roundTen(c.purchase_quantity||0),0))
function normalizeChoices(){choices.value=choices.value.map(x=>({...x,quantity:roundTen(x.quantity||0)})).filter(x=>x.quantity>0)}
function preview(row?:any){choices.value=(row?[row]:selected.value).flatMap(x=>x.channels.map((c:any)=>({...x,channel:c.channel,quantity:roundTen(c.purchase_quantity||0)}))).filter(x=>x.quantity>0);warehouse.value=options.warehouses[0]?.id;ack.value=false;requestId.value=uuid();planError.value='';planDialog.value=true}
let fingerprint=''
async function generate(){if(planBusy.value)return;normalizeChoices();if(!warehouse.value||choices.value.some(x=>!Number.isInteger(x.quantity)||x.quantity<0||x.quantity>planLimit(x))){planError.value='请选择收货仓库，并填写不超过取整后建议总量的数量';return}const totals:Record<string,number>={};for(const x of choices.value)totals[x.key]=(totals[x.key]||0)+x.quantity;if(!choices.value.some(x=>x.quantity>0)||choices.value.some(x=>totals[x.key]>planLimit(x))){planError.value='各渠道取整后合计须大于0，且不能超过允许的建议总量';return}if(uncertain.value&&!ack.value){planError.value='请先核对带有提醒的库存与到货信息';return}const body={warehouse_id:warehouse.value,rows:choices.value.filter(x=>x.quantity>0).map(x=>({key:x.key,token:x.token,channel:x.channel,quantity:x.quantity})),acknowledge_uncertain:ack.value};const f=JSON.stringify(body);if(fingerprint&&f!==fingerprint)requestId.value=uuid();fingerprint=f;planBusy.value=true;planError.value='';try{const d=await api('/replenishment/plans',{...body,request_id:requestId.value});planDialog.value=false;ElMessage.success(`已生成 ${d.count} 条分渠道采购计划，可在采购管理中继续处理`);await load()}catch(e){planError.value=(e as Error).message}finally{planBusy.value=false}}
onMounted(async()=>{try{Object.assign(options,await api('/replenishment/options'));if(!options.stores.includes(filters.store))filters.store=options.stores[0]||'';await load()}catch(e){error.value=(e as Error).message}})
watch(()=>props.initialStore,v=>{filters.store=v;search()})
</script>
<template>
<div class="replenishment-panel">
 <section class="replenish-banner"><div><small>普通商品 · 优先海运，缺口分渠道补齐</small><h2>{{filters.region==='UK'?'英国':'欧洲（德国入仓）'}}备货 {{data?.horizon??(filters.region==='UK'?67:77)}} 天</h2><p>{{filters.region==='UK'?50:60}} 天海运 ＋ {{data?.rule.safety_days??7}} 天安全库存 ＋ {{data?.rule.frequency_days??10}} 天发货频率</p></div><div><el-button v-if="admin&&data" @click="openRules">补货设置</el-button><el-button :loading="loading" @click="load">重新计算</el-button></div></section>
 <el-alert v-if="error" type="error" :title="error" :closable="false"/>
 <div v-if="data" class="replenish-cards"><article><span>区域商品</span><strong>{{format(data.overview.products)}}</strong><small>按店铺＋标品汇总</small></article><article><span>建议新增采购</span><strong>{{format(data.overview.needs)}} <small>款</small></strong><small>扣除已有采购计划</small></article><article><span>海运到货前有缺货风险</span><strong class="risk-number">{{format(data.overview.urgent)}} <small>款</small></strong><small>查看明细比较空派 / 卡航</small></article><article><span>未关联标品</span><strong>{{format(data.overview.unlinked)}}</strong><small>关联后可生成采购计划</small></article></div>
 <section class="panel">
 <div class="panel-head"><h2>补货建议</h2><div><el-button @click="emit('navigate','procurement')">查看采购计划</el-button><el-button v-if="admin" type="primary" :disabled="!selected.length||loading" @click="preview()">生成采购计划{{selected.length?`（${selected.length}）`:''}}</el-button></div></div>
 <form class="replenish-filters" @submit.prevent="search"><el-input v-model="filters.q" placeholder="标品编码 / 品名 / SKU / ASIN" clearable/><el-select v-model="filters.store" aria-label="补货店铺" @change="search"><el-option v-for="s in options.stores" :key="s" :value="s" :label="s"/></el-select><el-select v-model="filters.region" aria-label="补货区域" @change="search"><el-option value="UK" label="英国"/><el-option value="EU" label="欧洲（德国入仓）"/></el-select><el-select v-model="filters.sort" aria-label="补货排序" @change="search"><el-option value="need" label="建议采购量降序"/><el-option value="sales" label="日均销量降序"/><el-option value="cover" label="可售天数升序"/></el-select><el-button type="primary" native-type="submit">查询</el-button><TableReset table-key="ReplenishmentPanel/table-1"/></form>
 <div class="replenish-flags"><el-checkbox v-model="filters.only_need" @change="search">只看需要补货</el-checkbox><el-checkbox v-model="filters.only_linked" @change="search">只看已关联标品</el-checkbox><span>销量截至站点昨天 · 7 / 14 / 30 天加权 · 数量按销售包装计算</span></div>
 <el-alert v-if="data?.overview.unmapped_sales" :title="`近30天另有 ${data.overview.unmapped_sales} 件订单商品无法匹配当前 Listing，未纳入建议。`" type="warning" :closable="false"/>
 <template v-if="true"><el-table border data-width-key="ReplenishmentPanel/table-1" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-1', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-1', column, event)" :data="data?.rows||[]" v-loading="loading" row-key="key" @selection-change="(v:any[])=>selected=v" empty-text="暂无建议数据，请先同步该店铺区域的 Listing、订单及库存">
 <el-table-column :column-key="'column-1'" v-if="admin" type="selection" :width="tableWidths.width('table-1', 'column-1', '45')" :selectable="(r:any)=>r.can_generate"/>
 <el-table-column :column-key="'column-2'" label="图片" :width="tableWidths.width('table-1', 'column-2', '70')"><template #default="{row}"><el-image v-if="row.image_url" :src="row.image_url" fit="contain" class="replenish-image"/><span v-else>—</span></template></el-table-column>
 <el-table-column :column-key="'column-3'" :width="tableWidths.width('table-1', 'column-3', undefined)" label="标品编码 / 品名" min-width="250"><template #default="{row}"><strong>{{row.code}}</strong><div>{{row.name||'未关联标品'}}</div><small class="muted">{{row.skus.length}} 个 SKU · {{row.markets.join(' / ')}}</small></template></el-table-column>
 <el-table-column :column-key="'column-4'" label="7 / 14 / 30天销量" :width="tableWidths.width('table-1', 'column-4', '160')" align="center"><template #default="{row}">{{row.sales.map(format).join(' / ')}}</template></el-table-column>
 <el-table-column :column-key="'column-5'" label="加权日均" :width="tableWidths.width('table-1', 'column-5', '100')" align="center"><template #default="{row}">{{format(row.daily)}}<small v-if="!row.sales_complete" class="risk-text">历史待补齐</small></template></el-table-column>
 <el-table-column :column-key="'column-6'" label="FBA可售 / 可售天数" :width="tableWidths.width('table-1', 'column-6', '160')" align="center"><template #default="{row}">{{format(row.available)}} / {{format(row.cover_days)}} 天</template></el-table-column>
 <el-table-column :column-key="'column-7'" label="接收中 / 仓内处理" :width="tableWidths.width('table-1', 'column-7', '145')" align="center"><template #default="{row}">{{format(row.receiving)}} / {{format(row.processing)}}</template></el-table-column>
 <el-table-column :column-key="'column-8'" label="FBA在途" :width="tableWidths.width('table-1', 'column-8', '130')" align="center"><template #default="{row}">{{format(row.transit)}}<small class="muted">期内确认 {{format(row.eligible_transit)}}</small><small v-if="row.unknown_transit" class="risk-text">日期待核 {{format(row.unknown_transit)}}</small></template></el-table-column>
 <el-table-column :column-key="'column-9'" label="本地可用 / 本轮分配" :width="tableWidths.width('table-1', 'column-9', '155')" align="center"><template #default="{row}">{{format(row.local_available)}} / {{format(row.local_allocated)}}</template></el-table-column>
 <el-table-column :column-key="'column-10'" label="采购途中 / 期内可用" :width="tableWidths.width('table-1', 'column-10', '155')" align="center"><template #default="{row}">{{format(row.purchase_incoming)}} / {{format(row.purchase_eligible)}}</template></el-table-column>
 <el-table-column :column-key="'column-11'" label="发货已锁定 / 期内可用" :width="tableWidths.width('table-1', 'column-11', '175')" align="center"><template #default="{row}">{{format(row.dispatch_reserved)}} / {{format(row.dispatch_eligible)}}<small v-if="row.dispatch_pending" class="muted">待配货 {{format(row.dispatch_pending)}}</small></template></el-table-column>
 <el-table-column :column-key="'column-12'" label="已计划待采购" :width="tableWidths.width('table-1', 'column-12', '120')" align="center"><template #default="{row}">{{format(row.planned)}}</template></el-table-column>
 <el-table-column :column-key="'column-13'" label="本地建议发货" :width="tableWidths.width('table-1', 'column-13', '120')" align="center"><template #default="{row}">{{format(row.ready_to_ship)}}</template></el-table-column>
 <el-table-column :column-key="'column-14'" label="采购合计 / 空·卡·海" :width="tableWidths.width('table-1', 'column-14', '165')" align="center" fixed="right"><template #default="{row}"><strong class="suggest-number">{{format(row.procurement_need)}}</strong><small class="muted">{{row.channels.map((c:any)=>format(c.purchase_quantity)).join(" / ")}}</small></template></el-table-column>
 <el-table-column :column-key="'column-15'" :width="tableWidths.width('table-1', 'column-15', undefined)" label="补货状态" min-width="160"><template #default="{row}"><el-tag :type="row.risk==='库存充足'?'success':row.risk==='海运来不及'?'danger':'warning'">{{row.risk}}</el-tag><small v-if="row.shortage_date" class="muted">预计缺货 {{row.shortage_date}}</small><small v-if="row.issues.length" class="muted">{{row.issues.length}} 项需留意</small></template></el-table-column>
 <el-table-column :column-key="'column-16'" label="操作" :width="tableWidths.width('table-1', 'column-16', '145')" fixed="right"><template #default="{row}"><el-button link type="primary" @click="detail=row">计算明细</el-button><el-button v-if="admin" link type="primary" :disabled="!row.can_generate||loading" @click="preview(row)">采购</el-button></template></el-table-column>
 </el-table></template>
 <div class="replenish-footer"><span>计算时间：{{stamp(data?.calculated_at)}}</span><AppPagination v-model:current-page="page" :total="data?.total||0" @change="load" v-model:page-size="pageSize"/></div>
 </section>
 <p class="replenish-note">发货计划已锁定的库存按计划发货日期＋渠道时效计入供应；未配货部分不重复计数。本地可用量已扣除锁定量，并在店铺及区域间分配一次。采购途中只计入预计能赶上本轮的部分；日期不明的 FBA 在途暂不抵扣，并提示核对。新采购生产等待时间另计，备货时长从本地仓可发货时开始。</p>
 <el-dialog :model-value="!!detail" @update:model-value="(v:boolean)=>{if(!v)detail=null}" title="补货计算明细" width="min(900px,95vw)">
 <template v-if="detail"><h3>{{detail.code}} · {{detail.name}}</h3><div class="detail-formula"><p>加权日均＝{{detail.sales[0]}} ÷ 7 × 50% ＋ {{detail.sales[1]}} ÷ 14 × 30% ＋ {{detail.sales[2]}} ÷ 30 × 20%＝<b>{{format(detail.daily)}}</b></p><p>{{detail.horizon}} 天目标需求（向上取整）：<b>{{format(detail.target)}}</b>；FBA期内供应：<b>{{format(detail.supply)}}</b>（可售＋预计释放＋期内确认在途）</p><p>新增采购＝max(0，{{format(detail.target)}} − {{format(detail.supply)}} − 期内采购 {{format(detail.purchase_eligible)}} − 已安排发货 {{format(detail.dispatch_eligible)}} − 本地分配 {{format(detail.local_allocated)}} − 已计划 {{format(detail.planned)}})＝<b>{{format(detail.procurement_need)}}</b></p></div>
 <el-alert v-for="msg in detail.issues" :key="msg" :title="msg" type="warning" :closable="false"/>
 <el-alert v-if="detail.pre_air_shortage" :title="`最早空派到达前仍可能缺货约 ${detail.pre_air_shortage} 件，今天发货也无法补回这段缺口。`" type="warning" :closable="false"/><h4>现有及已安排供应的库存走势</h4><svg viewBox="0 0 750 190" class="stock-curve" role="img" aria-label="按加权日均销量推算FBA及已安排供应"><line x1="20" y1="160" x2="730" y2="160" stroke="#dce7e2"/><polyline :points="graph" fill="none" stroke="#207963" stroke-width="3"/><text x="20" y="185">今天</text><text x="650" y="185">第 {{detail.horizon}} 天</text></svg><p class="replenish-note">包含已锁定发货计划及有明确交期的采购途中，按预计到达日计入；不含未安排的本地库存和新增采购建议。缺货后库存按零计算，不累计负库存。预计期内缺货需求 {{format(detail.lost_units)}} 件。</p>
 <template v-if="true"><TableReset table-key="ReplenishmentPanel/table-2"/><el-table border data-width-key="ReplenishmentPanel/table-2" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-2', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-2', column, event)" :data="detail.channels"><el-table-column :column-key="'column-1'" :width="tableWidths.width('table-2', 'column-1', undefined)" label="渠道"><template #default="{row}">{{channelNames[row.channel]}}</template></el-table-column><el-table-column :column-key="'days'" :width="tableWidths.width('table-2', 'days', undefined)" prop="days" label="运输天数" align="center"/><el-table-column :column-key="'column-3'" :width="tableWidths.width('table-2', 'column-3', undefined)" label="建议新增采购"><template #default="{row}"><b>{{format(row.purchase_quantity)}}</b></template></el-table-column><el-table-column :column-key="'column-4'" :width="tableWidths.width('table-2', 'column-4', undefined)" label="本地建议发货"><template #default="{row}">{{format(row.local_quantity)}}</template></el-table-column><el-table-column :column-key="'planned_quantity'" :width="tableWidths.width('table-2', 'planned_quantity', undefined)" prop="planned_quantity" label="已计划待采购"/><el-table-column :column-key="'arrival'" :width="tableWidths.width('table-2', 'arrival', undefined)" prop="arrival" label="今天发货预计到达"/><el-table-column :column-key="'column-7'" :width="tableWidths.width('table-2', 'column-7', undefined)" label="能否赶上预计缺货"><template #default="{row}">{{row.before_shortage?'可赶上':'来不及，需另行处理'}}</template></el-table-column></el-table></template>
 <p class="replenish-note">接收与仓内处理暂按 {{detail.rule.processing_days}} 天后可售估算；到货日期为预计值。空派补到卡航到达，卡航补到海运到达，剩余安排海运；已有供应按预计到货时间扣除。各渠道合计等于本次建议量。采购等待时间会使到达日期顺延，需确认具备发货条件。</p><el-collapse><el-collapse-item title="SKU、到货依据与数据时间"><p>{{detail.skus.join(' / ')}}</p><p>库存：{{stamp(detail.inventory_at)}} · 订单最近更新：{{stamp(detail.orders_at)}}</p><p v-for="(e,i) in [...detail.events,...detail.purchase_events,...detail.dispatch_events]" :key="i">第 {{e.day}} 天：{{e.quantity}} 件 · {{e.source}}</p><p v-if="!detail.events.length&&!detail.purchase_events.length&&!detail.dispatch_events.length">暂无可确认到货事件</p></el-collapse-item></el-collapse>
 </template><template #footer><el-button @click="detail=null">关闭</el-button></template></el-dialog>
 <el-dialog v-model="ruleDialog" title="补货设置" width="520px" :close-on-click-modal="false"><el-alert v-if="ruleError" :title="ruleError" type="error" :closable="false"/><p>{{filters.store}} · {{filters.region==='UK'?'英国海运50天':'欧洲海运60天'}}</p><el-form label-position="top" :disabled="ruleBusy"><el-form-item label="安全库存天数"><el-input-number v-model="rule.safety_days" :min="0" :max="90" :precision="0"/></el-form-item><el-form-item label="发货频率（天）"><el-input-number v-model="rule.frequency_days" :min="1" :max="90" :precision="0"/></el-form-item><el-form-item label="接收及仓内处理预计释放天数"><el-input-number v-model="rule.processing_days" :min="1" :max="30" :precision="0"/></el-form-item></el-form><p>总备货时长：{{(filters.region==='UK'?50:60)+rule.safety_days+rule.frequency_days}} 天</p><template #footer><el-button :disabled="ruleBusy" @click="ruleDialog=false">取消</el-button><el-button type="primary" :loading="ruleBusy" @click="saveRules">保存并重新计算</el-button></template></el-dialog>
